import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第2季回归 | 这次我们来“趣谈Linux操作系统”","description":"","frontmatter":{},"headers":[],"relativePath":"趣谈网络协议/第2季回归-这次我们来“趣谈Linux操作系统”.md","filePath":"趣谈网络协议/第2季回归-这次我们来“趣谈Linux操作系统”.md","lastUpdated":1779822232000}'),s={name:"趣谈网络协议/第2季回归-这次我们来“趣谈Linux操作系统”.md"};function r(p,e,o,_,u,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第2季回归-这次我们来-趣谈linux操作系统" tabindex="-1">第2季回归 | 这次我们来“趣谈Linux操作系统” <a class="header-anchor" href="#第2季回归-这次我们来-趣谈linux操作系统" aria-label="Permalink to &quot;第2季回归 | 这次我们来“趣谈Linux操作系统”&quot;">​</a></h1><p>你好，我是你的老朋友刘超。在“趣谈网络协议”结课半年之后，我又给你带来了一个新的基础课程，“趣谈Linux操作系统”。</p><p>在咱们“趣谈网络协议”的留言里，我和同学们进行了很多互动，同时，我也和其他做基础知识专栏的作者有了不少交流，我发现，无论是从个人的职业发展角度，还是从公司招聘候选人的角度来看，扎实的基础知识是很多人的诉求。这让我更加坚信，我应该在“趣谈基础知识”这条道路上走下去。</p><p><strong>在设计“趣谈Linux操作系统”专栏的时候，我仍然秉承“趣谈”和“故事化”的方式，将枯燥的基础知识结合某个场景，给你生动、具象地讲述出来，帮你加深理解、巩固记忆、夯实基础。</strong></p><p>在我看来，操作系统在计算机中承担着“大管家”的角色，这个“大管家”就好比一家公司的老板，我们的目标就是把这家公司做上市，具体的过程，我用了一张图来表示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%A3%E8%B0%88%E7%BD%91%E7%BB%9C%E5%8D%8F%E8%AE%AE/images/87289/7d7b2f705d4877bb331b4ea3ff3450a5.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%A3%E8%B0%88%E7%BD%91%E7%BB%9C%E5%8D%8F%E8%AE%AE/images/87289/7d7b2f705d4877bb331b4ea3ff3450a5.jpg" alt=""></a></p><p>Linux操作系统中的概念非常多，数据结构也很多，流程也复杂，一般人在学习的过程中很容易迷路。我希望能够将这些复杂的概念、数据结构、流程通俗地讲解出来，争取每篇文章都用一张图串起这篇的知识点。</p><p>最终，整个专栏下来，你如果能把这些图都掌握了，你的知识就会形成体系和连接。在此基础上再进行深入学习，就会如鱼得水、易如反掌。</p><p>一段新的征途即将开始，期待与你继续同行。为了感谢老同学，我为你送上一张10元专属优惠券，可以与限时优惠同享，优惠券有效期仅5天，建议你抓紧使用。点击下方图片，可试读专栏最新文章。</p><p>我们新专栏见！</p><p><a href="https://time.geekbang.org/column/intro/164?utm_term=zeusOLMNR&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=164-presell&amp;utm_content=qutanwangluoxieyi" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%A3%E8%B0%88%E7%BD%91%E7%BB%9C%E5%8D%8F%E8%AE%AE/images/87289/57f047be7ebb1f4aba7e8064e1c11544.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%A3%E8%B0%88%E7%BD%91%E7%BB%9C%E5%8D%8F%E8%AE%AE/images/87289/57f047be7ebb1f4aba7e8064e1c11544.jpg" alt=""></a></a></p>',11)])])}const E=t(s,[["render",r]]);export{l as __pageData,E as default};
